 private String appearance(){return prefs.config().optString("ui_theme")+":"+new java.io.File(getFilesDir(),"images/logo.png").lastModified()+":"+new java.io.File(getFilesDir(),"images/background.png").lastModified();}
 private void refresh(){if(!appearance.isEmpty()&&!appearance.equals(appearance())){recreate();return;}status.setText(NotifyService.running?"●  RECEPTOR ATIVO":"○  RECEPTOR PARADO");status.setTextColor(NotifyService.running?LIME:MUTED);permission.setText(Settings.canDrawOverlays(this)?"✓  Sobreposição autorizada":"Autorize os avisos sobre outros aplicativos.");address.setText(NetworkInfo.primary().replace("https://","").replace(":8766",""));error.setText(NotifyService.lastError);}
 private void start(boolean test){if(!Ui.accepted(this)){Ui.termsDialog(this,true,()->start(test));return;}if(!Settings.canDrawOverlays(this)){toast("Primeiro autorize aparecer sobre outros apps.");grant();return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},10);prefs.enabled(true);try{startForegroundService(new Intent(this,NotifyService.class).setAction(test?"TEST":"START"));handler.postDelayed(this::refresh,250);if(test&&prefs.config().optBoolean("paused"))toast("Retome os avisos pelo app CasaNotify Controle.");}catch(RuntimeException e){prefs.enabled(false);NotifyService.lastError="O Android bloqueou o início. Tente novamente com o app aberto.";refresh();}}
 private void grant(){try{startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}catch(ActivityNotFoundException e){try{startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION));}catch(ActivityNotFoundException x){new AlertDialog.Builder(this).setTitle("Permissão da TV").setMessage("Abra Configurações → Aplicativos → Acesso especial → Exibir sobre outros apps. Autorize CasaNotify TV. Consulte o guia caso sua TV não ofereça essa opção.").setPositiveButton("Entendi",null).show();}}}
 private void pair(){if(!NotifyService.running){toast("Ative o receptor antes de vincular.");return;}String code=Pairing.issue();LinearLayout body=column();body.setPadding(dp(24),dp(16),dp(24),dp(20));body.addView(text("Na integração CasaNotify TV 2.1.0 do Home Assistant, configure a TV descoberta. Receptor:",16,MUTED,false));body.addView(text(NetworkInfo.primary(),21,TEXT,true));TextView digits=text(code.substring(0,3)+" "+code.substring(3),48,LIME,true);digits.setGravity(Gravity.CENTER);digits.setPadding(0,dp(16),0,dp(16));body.addView(digits);body.addView(text("Digite os seis números. Válido por dois minutos e uma vinculação.",15,MUTED,false));new AlertDialog.Builder(this).setTitle("Vincular Home Assistant").setView(body).setPositiveButton("Concluído",(d,w)->Pairing.cancel()).setOnCancelListener(d->Pairing.cancel()).show();}
