 private void customize(){ScrollView sc=new ScrollView(this);LinearLayout fields=column();fields.setPadding(dp(24),dp(12),dp(24),dp(16));sc.addView(fields);JSONObject old=prefs.defaults();Spinner theme=spinner(fields,"Tema",new String[]{"Jardim · verde","Oceano · azul","Âmbar · laranja","Aurora · rosa","Papel · claro"},Notice.THEMES,old.optString("theme","lime")),position=spinner(fields,"Posição",new String[]{"Superior esquerdo","Superior centro","Superior direito","Centro esquerdo","Centro","Centro direito","Inferior esquerdo","Inferior centro","Inferior direito"},Notice.POSITIONS,old.optString("position","top_right"));EditText duration=input(fields,"Duração (3–120 segundos)",old.optInt("duration",10)),width=input(fields,"Largura (260–800 dp)",old.optInt("width",380)),size=input(fields,"Fonte (14–36)",old.optInt("text_size",18));fields.addView(text("Cores livres, imagens, som, transparência, cantos e horário silencioso: use o app CasaNotify Controle.",14,MUTED,false));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Personalizar avisos").setView(sc).setPositiveButton("Salvar",null).setNegativeButton("Cancelar",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{JSONObject d=new JSONObject(old.toString());String t=Notice.THEMES[theme.getSelectedItemPosition()];if(!t.equals(old.optString("theme","lime")))for(String k:new String[]{"background","text_color","accent"})d.remove(k);d.put("theme",t).put("position",Notice.POSITIONS[position.getSelectedItemPosition()]).put("duration",Integer.parseInt(duration.getText().toString())).put("width",Integer.parseInt(width.getText().toString())).put("text_size",Integer.parseInt(size.getText().toString()));prefs.update(new JSONObject().put("defaults",d));showPreview();dialog.dismiss();toast("Aparência salva.");}catch(Exception e){toast("Confira os valores: "+e.getMessage());}}));dialog.show();}
