 private Spinner spinner(LinearLayout root,String label,String[] names,String[] ids,String value){root.addView(text(label,14,MUTED,false));Spinner s=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,names);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(a);for(int i=0;i<ids.length;i++)if(ids[i].equals(value))s.setSelection(i);root.addView(s,new LinearLayout.LayoutParams(-1,dp(50)));return s;}
